    private boolean contains(Iterator iterator, Object object) {
        while (iterator.hasNext()) {
            if (equal(null, iterator.next(), object)) {
                return true;
            }
        }
        return false;
    }

    private boolean findMatch(Iterator iterator1, Iterator iterator2) {
        while (iterator1.hasNext()) {
            if (iterator2.hasNext()) {
                if (!equal(null, iterator1.next(), iterator2.next())) {
                    return false;
                }
            } else {
                return false;
            }
        }
        return !iterator2.hasNext();
    }
